#include "Monstey_NavSeamMatcher.hpp"
#include "Monstey_Core.hpp"
#include <bit>
#include <cstring>
#include <iostream>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using J=Monstey_Json;using C=Monstey_NavSeamCandidate;
struct Mesh{Monstey_Bytes faces=Monstey_Bytes(16),edges=Monstey_Bytes(80),vertices=Monstey_Bytes(64);std::array<std::int32_t,1>fm{-1};std::array<std::int32_t,4>em{-1,-1,-1,-1};Monstey_NavigationAabb bounds{};Monstey_NavigationBoundaryMeshView View()const{Monstey_NavigationBoundaryMeshView m{};m.faces=faces;m.edges=edges;m.vertices=vertices;m.face_map=fm;m.edge_map=em;m.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return m;}};
Mesh Quad(bool second){Mesh m;const std::array<V,4>p=second?std::array<V,4>{V{2,0,0,0},V{0,0,0,0},V{0,0,2,0},V{2,0,2,0}}:std::array<V,4>{V{0,0,0,0},V{2,0,0,0},V{2,0,-2,0},V{0,0,-2,0}};m.bounds=second?Monstey_NavigationAabb{V{0,0,0,0},V{2,0,2,0}}:Monstey_NavigationAabb{V{0,0,-2,0},V{2,0,0,0}};Monstey_PutU16(m.faces,8,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(m.edges,i*20,i);Monstey_PutU32(m.edges,i*20+4,(i+1)%4);Monstey_PutU32(m.edges,i*20+8,0xffffffff);Monstey_PutU32(m.edges,i*20+12,0xffffffff);std::memcpy(m.vertices.data()+16*i,p[i].data(),16);}return m;}
C Candidate(unsigned b,float score,float low,float high){return C{0,0x400000u|b,0,0x400000u,score,1,1,true,{low,high,0,1}};}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0;auto a=Quad(false),b=Quad(true);auto av=a.View(),bv=b.View();const V up{0,1,0,0};Monstey_NavSeamSettings s{{.5f,.1f,.01f,.0001f,.9f,.9f,.02f},.9f,.9f};auto Pair=[&](const auto&x,const auto&y,unsigned fa,unsigned fb,const auto&settings,int expected){const auto got=Monstey_NavSeamMatchEdgePair(x,y,0,0,0,0,static_cast<std::uint8_t>(fa),static_cast<std::uint8_t>(fb),up,settings);Monstey_Require(got.status==expected,std::string("Full pair group ")+std::to_string(groups)+" expected "+std::to_string(expected)+" got "+std::to_string(got.status));++groups;return got;};const auto ground=Pair(av,bv,0,0,s,-1),alternate=Pair(av,bv,1,1,s,-1);Pair(av,bv,0,1,s,-1);Pair(av,bv,1,0,s,-1);Pair(av,bv,0xfe,0x80,s,-1);Pair(av,bv,0xff,0x81,s,-1);auto translatedB=bv;translatedB.transform[3]=V{0,.05f,0,0};const auto gappedGround=Pair(av,translatedB,0,0,s,-1),gappedAlternate=Pair(av,translatedB,1,1,s,-1),mixed=Pair(av,translatedB,0,1,s,-1);Monstey_Require(mixed.candidate.score==(gappedAlternate.candidate.score+gappedGround.candidate.score)*.5f&&std::abs(mixed.candidate.score-.00125f)<.00001f,"Mixed candidate score was not native averaged result");Monstey_Require(mixed.candidate.horizontal_cosine==(gappedAlternate.candidate.horizontal_cosine+gappedGround.candidate.horizontal_cosine)*.5f&&mixed.candidate.overlap==(gappedAlternate.candidate.overlap+gappedGround.candidate.overlap)*.5f,"Mixed candidate metadata was not averaged");for(unsigned i=0;i<4;i+=2)Monstey_Require(mixed.candidate.intervals[i]>=gappedGround.candidate.intervals[i]&&mixed.candidate.intervals[i+1]<=gappedGround.candidate.intervals[i+1],"Mixed intervals do not intersect ground intervals");auto tilted=b;const std::array<V,4>t{V{2,0,0,0},V{0,2,0,0},V{0,2,2,0},V{2,0,2,0}};for(unsigned i=0;i<4;++i)std::memcpy(tilted.vertices.data()+16*i,t[i].data(),16);auto permissive=s;permissive.ground.step_height=4;permissive.ground.direction_cosine=.6f;permissive.face_cosine=.1f;permissive.alternate_edge_cosine=.95f;Pair(av,tilted.View(),0,0,permissive,-1);Pair(av,tilted.View(),1,1,permissive,13);Pair(av,tilted.View(),0,1,permissive,13);Pair(av,av,0,1,s,0);std::array<std::uint8_t,6>leaf{};Monstey_NavigationCompactTreeView treeA{leaf,a.bounds},treeB{leaf,b.bounds};auto Whole=[&](const auto&x,const auto&y,unsigned fa,unsigned fb,float tolerance,const auto&settings){++groups;return Monstey_NavSeamMatchMeshes(x,y,a.bounds,b.bounds,treeA,treeB,static_cast<std::uint8_t>(fa),static_cast<std::uint8_t>(fb),up,tolerance,settings);};const auto groundPipeline=Whole(av,bv,0,0,.01f,s);for(const auto [flagsA,flagsB]:{std::pair{1u,1u},std::pair{0u,1u},std::pair{1u,0u},std::pair{0xfeu,0x80u},std::pair{0xffu,0x81u}}){const auto got=Whole(av,bv,flagsA,flagsB,.01f,s);Monstey_Require(got.connections==groundPipeline.connections&&got.coincident_connections==1,"Full flag route changed coincident connection");}auto shifted=bv;shifted.transform[3]=V{1,0,0,0};for(const auto[flagsA,flagsB]:{std::pair{0u,0u},std::pair{1u,1u},std::pair{0u,1u},std::pair{1u,0u}}){const auto got=Whole(av,shifted,flagsA,flagsB,.01f,s);Monstey_Require(got.connections==groundPipeline.connections&&got.coincident_connections==0&&got.candidates.size()==1&&got.candidates[0].enabled,"Full flag route partial-overlap fallback failed");}auto narrow=s;narrow.ground.horizontal_gap=.01f;Pair(av,translatedB,1,1,narrow,2);const auto bypass=Whole(av,translatedB,1,1,.1f,narrow);Monstey_Require(bypass.coincident_connections==1&&bypass.connections==groundPipeline.connections,"Native coincident pass must precede alternate gap rejection");const auto rejected=Whole(av,translatedB,1,1,.01f,narrow);Monstey_Require(rejected.connections.empty(),"Alternate gap rejection absent after failed coincident pass");const auto expanded=Whole(av,bv,0,1,.01f,s);Monstey_Require(std::abs(expanded.boundary_a.local_query.minimum[0]+.25f)<1e-6f&&std::abs(expanded.boundary_b.local_query.minimum[0]+.05f)<1e-6f,"Mixed per-mesh half expansions differ from native flag policy");Monstey_Require(ground.candidate.edge_a==alternate.candidate.edge_a&&ground.candidate.edge_b==alternate.candidate.edge_b,"Route identity differs");Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"route_profiles",J::array({"00","11","01","10"})},{"high_flag_bits_ignored",true},{"original_program_called",false},{"process_accessed",false},{"scope","Full 557F20 ground/alternate/mixed geometry under explicit NULL pair callback and owned native compact trees"}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" full native flag-route groups\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}